effect.shader:
void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 uv = (acScreenNorm - origin) * vec2(acAspect, 1.0) * max(cells, 1.0);

    float rad = radians(angle);
    float co = cos(rad);
    float si = sin(rad);
    uv = vec2(uv.x * co - uv.y * si, uv.x * si + uv.y * co);

    // Onda triangular em cada eixo, multiplicadas: o produto troca de sinal a
    // cada célula em X e a cada célula em Y, que é exatamente um xadrez.
    vec2 wave = abs(fract(uv * 0.5) * 2.0 - 1.0) * 2.0 - 1.0;
    float board = wave.x * wave.y;

    float soft = max(softness, 0.0005);
    float mask = smoothstep(-soft, soft, board);

    vec4 pattern = mix(colorB, colorA, mask);
    fragColor = vec4(pattern.rgb, pattern.a * original.a);
}
